// One item per watched place: the subreddits and the n8n forum categories of Answers.
const a = $('Answers').first().json;
const list = (s) => String(s ?? '').split(',').map((p) => p.trim()).filter(Boolean);
return [...list(a.subreddits).map((place) => ({ json: { source: 'reddit', place } })),
        ...list(a.n8n_categories).map((place) => ({ json: { source: 'n8n', place } }))];

// One item per new post, in one shape whatever the forum: n8n_qualifier's lib/sources.js.
const since = new Date(Date.now() - 24 * 3600e3).toISOString();
return $input.all().flatMap(({ json: run }) => {
  const r = run.result ?? {};
  if (run.script?.includes('reddit.com'))
    return (r.threads ?? []).map((t) => ({ json: { url: t.url, source: 'reddit', place: r.subreddit, title: t.title ?? '', author: t.author ?? null, created: t.created ?? null, post_type: t.post_type ?? null, content_href: t.content_href ?? null, op_text: t.body ?? null, op_text_known: t.body_known ? 1 : 0 } }));
  return (r.topics ?? []).filter((t) => !t.pinned && String(t.createdAt ?? '') >= since)
    .map((t) => ({ json: { url: t.url, source: 'n8n', place: String(t.categoryId), title: t.title ?? '', author: t.author ?? null, created: t.createdAt ?? null, post_type: null, content_href: null, op_text: null, op_text_known: 0 } }));
});

// The page and its replies, as the model and the reviewer read them: n8n_qualifier's evidenceOf.
const post = $('Not seen before').item.json;
const page = $json.result ?? {};
let read, comments;
if (post.source === 'reddit') {
  read = { score: page.score ?? null, num_comments: page.num_comments ?? null };
  comments = (page.comments ?? []).map((c) => ({ author: c.author ?? null, body: c.body ?? '', score: c.score ?? null, depth: c.depth ?? 0, created: c.created ?? null }));
  post.op_text = String(page.op_text ?? '').trim() || null;
} else {
  const [op, ...replies] = (page.posts ?? []).filter((p) => !p.action);
  read = { score: page.likeCount ?? null, num_comments: page.postsCount == null ? null : page.postsCount - 1 };
  comments = replies.map((p) => ({ author: p.username ?? null, body: p.text ?? '', score: p.likeCount ?? null, depth: p.replyToPostNumber ? 1 : 0, created: p.createdAt ?? null }));
  post.op_text = String(op?.text ?? '').trim() || null;
}
post.op_text_known = 1;

const WHO = { reddit: 'u/', n8n: '@' };
const VOTES = { reddit: 'points', n8n: 'likes' };
const who = (name) => (WHO[post.source] ?? '') + (name ?? '(deleted)');
const place = post.source === 'n8n' ? 'n8n forum › ' + post.place : 'r/' + post.place;
const byline = [place, who(post.author), post.created ? 'posted ' + post.created : null,
  read.score == null ? null : read.score + ' ' + VOTES[post.source],
  read.num_comments == null ? null : read.num_comments + ' comments',
  post.post_type ? post.post_type + ' post' : null].filter(Boolean).join(' · ');
const head = ['<div class="rd-byline">' + byline + '</div>', '# ' + String(post.title ?? '').trim(), '<div class="rd-link">' + post.url + '</div>'];
if (post.content_href && post.content_href !== post.url) head.push('<div class="rd-link">links to: ' + post.content_href + '</div>');
const lines = comments.map((c) => {
  const depth = Math.min(Math.max(0, Number(c.depth ?? 0)), 6);
  const op = post.author && c.author && c.author.toLowerCase() === String(post.author).toLowerCase();
  const meta = [c.score == null ? null : c.score + ' ' + VOTES[post.source], c.created].filter(Boolean).join(' · ');
  return '<div class="rd-c rd-d' + depth + (op ? ' rd-own' : '') + '"><div class="rd-cwho">' + who(c.author) + (op ? ' (OP)' : '') + (meta ? ' · ' + meta : '') + '</div>\n' + String(c.body ?? '').trim() + '\n</div>';
});
const total = read.num_comments;
const count = total != null && total !== comments.length ? comments.length + ' of ' + total + ' shown' : String(comments.length);
const evidence = [head.join('\n'), '## Post', post.op_text || '(the OP wrote no text)',
  '## Comments (' + count + ')', lines.length ? lines.join('\n') : '(nobody has replied to this post)'].join('\n\n');
return { json: { input: { post, read, comments }, evidence } };

