  "type": "object",
  "required": [
    "reply"
  ],
  "properties": {
    "reply": {
      "type": "string",
      "pattern": "^(?![\\s\\S]*(?:https?://|www\\.))[\\s\\S]*$",
      "description": "the reply, exactly as it would be posted"
    }
  },
  "additionalProperties": false
}

